const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/workflow_instances',
  qs: {
    company_id: 'SOME_INTEGER_VALUE',
    'filters[workflowed_object_id]': 'SOME_INTEGER_VALUE',
    'filters[workflowed_object_type]': 'SOME_STRING_VALUE',
    project_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/workflow_instances?company_id=SOME_INTEGER_VALUE&filters%5Bworkflowed_object_id%5D=SOME_INTEGER_VALUE&filters%5Bworkflowed_object_type%5D=SOME_STRING_VALUE&project_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

